package com.oracle.observability.kafka.connect;

import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import org.apache.kafka.clients.consumer.OffsetAndMetadata;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.connect.errors.ConnectException;
import org.apache.kafka.connect.errors.DataException;
import org.apache.kafka.connect.errors.RetriableException;
import org.apache.kafka.connect.sink.SinkRecord;
import org.apache.kafka.connect.sink.SinkTaskContext;
import org.junit.jupiter.api.Test;

class OracleObservabilitySinkTaskTest {
    @Test
    void successfulPutAllowsCommitAndStopClosesUploader() {
        FakeUploader uploader = new FakeUploader();
        var task = task(uploader);
        task.start(TestFixtures.properties());
        task.put(TestFixtures.records(250));
        assertEquals(List.of(100, 100, 50), uploader.accepted.stream().map(PreparedChunk::recordCount).toList());
        var offsets = offsets(250);
        assertEquals(offsets, task.preCommit(offsets));
        assertDoesNotThrow(() -> task.flush(offsets));
        task.stop();
        task.stop();
        assertEquals(1, uploader.closes);
    }

    @Test
    void retriesOnlyFailedChunkWithSameBytesAndTokenBeforeCommitting() {
        FakeUploader uploader = new FakeUploader();
        uploader.failAt = 1;
        uploader.failure = new RetriableException("503");
        var task = task(uploader);
        AtomicLong retry = new AtomicLong();
        task.initialize(context(retry));
        task.start(TestFixtures.properties());
        var records = TestFixtures.records(250);
        assertThrows(RetriableException.class, () -> task.put(records));
        assertEquals(1, uploader.accepted.size());
        assertTrue(task.preCommit(offsets(250)).isEmpty());
        assertThrows(RetriableException.class, () -> task.flush(offsets(250)));
        assertTrue(retry.get() > 0);
        PreparedChunk failed = uploader.attempts.get(1);
        task.put(new ArrayList<>(records));
        assertSame(failed, uploader.attempts.get(2));
        assertEquals(3, uploader.accepted.size());
        assertEquals(offsets(250), task.preCommit(offsets(250)));
    }

    @Test
    void fatalUploadFailureCannotBecomeACommit() {
        FakeUploader uploader = new FakeUploader();
        uploader.failAt = 0;
        uploader.failure = new ConnectException("invalid destination");
        var task = task(uploader);
        task.start(TestFixtures.properties());
        assertThrows(ConnectException.class, () -> task.put(TestFixtures.records(1)));
        assertTrue(task.preCommit(offsets(1)).isEmpty());
    }

    @Test
    void validatesWholeCallBeforeUploadingAnyChunk() {
        FakeUploader uploader = new FakeUploader();
        var task = task(uploader);
        task.start(TestFixtures.properties());
        List<SinkRecord> records = new ArrayList<>(TestFixtures.records(100));
        records.add(TestFixtures.record(0, 100, null));
        assertThrows(DataException.class, () -> task.put(records));
        assertTrue(uploader.attempts.isEmpty());
    }

    @Test
    void yieldsAfterBudgetAndResumesInsteadOfResendingAcceptedChunks() {
        AtomicLong nanos = new AtomicLong();
        FakeUploader uploader = new FakeUploader() {
            @Override public void upload(PreparedChunk chunk) {
                super.upload(chunk);
                nanos.addAndGet(60_000_000_000L);
            }
        };
        var task = new OracleObservabilitySinkTask(unused -> uploader, nanos::get);
        task.start(TestFixtures.properties());
        var records = TestFixtures.records(250);
        assertThrows(RetriableException.class, () -> task.put(records));
        assertTrue(task.preCommit(offsets(250)).isEmpty());
        assertThrows(RetriableException.class, () -> task.put(records));
        task.put(records);
        assertEquals(3, uploader.accepted.size());
        assertEquals(3, uploader.attempts.size());
        assertEquals(offsets(250), task.preCommit(offsets(250)));
    }

    @Test
    void refusesDifferentInputWhileCallIsPending() {
        FakeUploader uploader = new FakeUploader();
        uploader.failAt = 0;
        uploader.failure = new RetriableException("503");
        var task = task(uploader);
        task.start(TestFixtures.properties());
        assertThrows(RetriableException.class, () -> task.put(TestFixtures.records(1)));
        assertThrows(ConnectException.class, () -> task.put(TestFixtures.records(2)));
    }

    @Test
    void revocationDiscardsMemoryAndReliesOnUncommittedKafkaReplay() {
        FakeUploader uploader = new FakeUploader();
        uploader.failAt = 0;
        uploader.failure = new RetriableException("timeout");
        var task = task(uploader);
        task.start(TestFixtures.properties());
        assertThrows(RetriableException.class, () -> task.put(TestFixtures.records(2)));
        task.close(List.of(new TopicPartition("la-hackathon-logs", 0)));
        task.put(TestFixtures.records(1));
        assertEquals(1, uploader.accepted.size());
    }

    @Test
    void emptyPutDoesNotUploadAndRetryDelayIsCapped() {
        FakeUploader uploader = new FakeUploader();
        var task = task(uploader);
        AtomicLong retry = new AtomicLong();
        task.initialize(context(retry));
        var props = TestFixtures.properties();
        props.put(OracleObservabilitySinkConfig.RETRY_INITIAL_MS, "1000");
        props.put(OracleObservabilitySinkConfig.RETRY_MAX_MS, "1000");
        task.start(props);
        task.put(List.of());
        assertTrue(uploader.attempts.isEmpty());
        uploader.failAt = 0;
        uploader.failure = new RetriableException("429");
        assertThrows(RetriableException.class, () -> task.put(TestFixtures.records(1)));
        assertTrue(retry.get() > 0 && retry.get() <= 1000);
    }

    private static OracleObservabilitySinkTask task(FakeUploader uploader) {
        return new OracleObservabilitySinkTask(unused -> uploader, System::nanoTime);
    }

    private static Map<TopicPartition, OffsetAndMetadata> offsets(long next) {
        return Map.of(new TopicPartition("la-hackathon-logs", 0), new OffsetAndMetadata(next));
    }

    private static SinkTaskContext context(AtomicLong timeout) {
        return (SinkTaskContext) Proxy.newProxyInstance(SinkTaskContext.class.getClassLoader(),
                new Class<?>[] {SinkTaskContext.class}, (proxy, method, args) -> {
                    if (method.getName().equals("timeout")) { timeout.set((Long) args[0]); }
                    return null;
                });
    }

    private static class FakeUploader implements LogEventsUploader {
        final List<PreparedChunk> accepted = new ArrayList<>();
        final List<PreparedChunk> attempts = new ArrayList<>();
        int failAt = -1;
        RuntimeException failure;
        int closes;
        @Override public void upload(PreparedChunk chunk) {
            attempts.add(chunk);
            if (attempts.size() - 1 == failAt) { throw failure; }
            accepted.add(chunk);
        }
        @Override public void close() { closes++; }
    }
}
